/* Сгенерировано из services/apps/sdk/styles/app.css. Не редактировать вручную. */
export const appStylesheet = "/* Общий визуальный слой приложений Искры.\n\n   Приложение получает его целиком: `appStylesheetResponse` отдаёт этот файл\n   маршрутом самого приложения, а `appPage` подключает ссылкой. Автору не нужно\n   ни писать оформление, ни класть файл в бандл — слой едет внутри @iskra/apps\n   и пристёгнут к версии бандла, как и остальные закрытые зависимости.\n\n   Палитра взята из design-guide Искры, чтобы приложение не выглядело чужим\n   рядом с ней: тёплый нейтральный фон, амбер единственным акцентом, границы\n   низкой контрастности. Значения продублированы здесь намеренно — бандл\n   приложения закрытый, тянуть стили Искры ему неоткуда.\n\n   Внешних ресурсов нет ни одного: рекомендуемая политика содержимого\n   (default-src 'self') загрузку со стороны запрещает, поэтому шрифт —\n   системный стек, знак бренда — inline SVG в разметке, а маркеры и крутилка\n   нарисованы средствами CSS.\n\n   Оформлены и голые элементы (main, h1, table, button, input), а не только\n   классы: экран, собранный без единого класса, обязан выглядеть законченным —\n   классы уточняют раскладку, а не включают её. */\n\n:root {\n  color-scheme: light dark;\n\n  --bg: #fbf9f7;\n  --panel: #f6f3f1;\n  --surface: #ffffff;\n  --surface-sunken: #faf8f6;\n\n  --text: #171717;\n  --text-soft: #6e6e6e;\n  --text-muted: #959595;\n\n  --border: rgb(55 50 47 / 12%);\n  --border-strong: rgb(55 50 47 / 22%);\n  --hover: rgb(131 121 114 / 10%);\n\n  --accent: #aa5c03;\n  --accent-hover: #d97706;\n  --accent-contrast: #ffffff;\n  --accent-soft: rgb(253 205 166 / 35%);\n  --accent-border: rgb(170 92 3 / 35%);\n\n  --success: #047857;\n  --success-soft: rgb(4 120 87 / 10%);\n  --danger: #dc2626;\n  --danger-soft: rgb(220 38 38 / 10%);\n  --danger-border: rgb(220 38 38 / 25%);\n\n  --radius: 10px;\n  --radius-sm: 7px;\n  --shadow: 0 1px 2px rgb(23 23 23 / 4%), 0 4px 16px rgb(23 23 23 / 5%);\n\n  --font: 14px/1.55 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --page-width: 1180px;\n\n  /* Цвета шапки. В базе шапка — та же панель, что и боковое меню; стиль\n     «Строгий» делает её тёмной, не трогая --panel. Ссылки на токены\n     вычисляются на :root, поэтому следуют и за тёмной темой, и за стилем. */\n  --bar-bg: var(--panel);\n  --bar-text: var(--text);\n  --bar-text-soft: var(--text-soft);\n  --bar-hover: var(--hover);\n  --bar-border: var(--border);\n}\n\n/* Тёмная тема идёт по системной настройке: приложение открывают из Искры, и\n   собственного переключателя у него нет — расхождение с окном вокруг читалось\n   бы как чужая вкладка. */\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg: #1d1d1c;\n    --panel: #191818;\n    --surface: #2b2a29;\n    --surface-sunken: #232221;\n\n    --text: #ffffff;\n    --text-soft: #bfbfbf;\n    --text-muted: #858585;\n\n    --border: rgb(232 224 217 / 12%);\n    --border-strong: rgb(241 239 237 / 22%);\n    --hover: rgb(170 165 160 / 10%);\n\n    --accent: #f4cd74;\n    --accent-hover: #eaba4d;\n    --accent-contrast: #1d1d1c;\n    --accent-soft: rgb(199 93 7 / 22%);\n    --accent-border: rgb(244 205 116 / 35%);\n\n    --success: #3dd2a8;\n    --success-soft: rgb(61 210 168 / 12%);\n    --danger: #ff4848;\n    --danger-soft: rgb(255 72 72 / 12%);\n    --danger-border: rgb(255 72 72 / 28%);\n\n    --shadow: 0 1px 2px rgb(0 0 0 / 20%), 0 4px 16px rgb(0 0 0 / 24%);\n  }\n}\n\n/* ── Стили оформления ──────────────────────────────────────────────────── */\n\n/* Стиль — атрибут data-style на <html>, который ставит appPage. Блок стиля\n   переопределяет только токены: компоненты ниже одни на все стили.\n\n   Селектор :root[data-style=…] сильнее тёмного :root внутри @media, поэтому\n   тёмный блок стиля обязан переопределять ВСЕ токены светлого блока того же\n   стиля: пропущенный токен остался бы светлым на тёмном фоне. Паритет\n   наборов сверяет тест SDK.\n\n   Контраст (WCAG, вычислен по формуле относительной яркости), все ≥ 4.5:1:\n   strict, светлая:  --accent #2f5d8a / --accent-contrast #ffffff   6.88\n                     --accent-hover #244a70 / #ffffff               9.18\n                     --bar-text #e8edf3 / --bar-bg #1f2a37         12.35\n                     --bar-text-soft #aab6c3 / --bar-bg #1f2a37     7.05\n                     --text #1b2430 / --bg #f4f6f8                 14.45\n   strict, тёмная:   --accent #7fb0e0 / --accent-contrast #0f151b   8.04\n                     --accent-hover #9cc3ea / #0f151b               9.98\n                     --bar-text #e8edf3 / --bar-bg #0f151b         15.60\n                     --bar-text-soft #aab6c3 / --bar-bg #0f151b     8.91\n                     --text #e8edf3 / --bg #141a21                 14.87\n   showcase, светлая: --accent #c2461d / --accent-contrast #ffffff  5.01\n                     --accent-hover #a63a15 / #ffffff               6.49\n                     --text #2a1a0f / шапка #fff8ee                15.89\n                     --text-soft #7a5a44 / шапка #fff8ee            5.90\n                     --accent #c2461d / --bg #fff8ee (ссылка)       4.76\n   showcase, тёмная: --accent #ff9a6b / --accent-contrast #1f1712   8.48\n                     --accent-hover #ffb28e / #1f1712              10.10\n                     --text #fbeee0 / шапка #1f1712                15.47\n                     --text-soft #d2b8a3 / шапка #1f1712            9.35 */\n\n/* «Строгий»: плотный, для учёта и отчётов — холодный серо-синий, мелкий\n   радиус, тёмная шапка. */\n:root[data-style=\"strict\"] {\n  --bg: #f4f6f8;\n  --panel: #eef1f4;\n  --surface: #ffffff;\n  --surface-sunken: #f7f9fb;\n\n  --text: #1b2430;\n  --text-soft: #556270;\n  --text-muted: #7d8a98;\n\n  --border: rgb(27 36 48 / 12%);\n  --border-strong: rgb(27 36 48 / 22%);\n  --hover: rgb(47 93 138 / 8%);\n\n  --accent: #2f5d8a;\n  --accent-hover: #244a70;\n  --accent-contrast: #ffffff;\n  --accent-soft: rgb(47 93 138 / 12%);\n  --accent-border: rgb(47 93 138 / 35%);\n\n  --radius: 4px;\n  --radius-sm: 3px;\n  --font: 13px/1.45 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n\n  --bar-bg: #1f2a37;\n  --bar-text: #e8edf3;\n  --bar-text-soft: #aab6c3;\n  --bar-hover: rgb(232 237 243 / 10%);\n  --bar-border: rgb(232 237 243 / 22%);\n}\n\n/* «Витрина»: крупный, для клиентов — светлый тёплый фон, крупный кегль,\n   большой радиус, засечки в заголовках, коралловый акцент. */\n:root[data-style=\"showcase\"] {\n  --bg: #fff8ee;\n  --panel: #fff8ee;\n  --surface: #ffffff;\n  --surface-sunken: #fdf1e2;\n\n  --text: #2a1a0f;\n  --text-soft: #7a5a44;\n  --text-muted: #a88c77;\n\n  --border: rgb(122 70 30 / 14%);\n  --border-strong: rgb(122 70 30 / 26%);\n  --hover: rgb(194 70 29 / 8%);\n\n  --accent: #c2461d;\n  --accent-hover: #a63a15;\n  --accent-contrast: #ffffff;\n  --accent-soft: rgb(224 88 43 / 14%);\n  --accent-border: rgb(194 70 29 / 35%);\n\n  --radius: 16px;\n  --radius-sm: 12px;\n  --font: 15px/1.6 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --font-display: Georgia, \"Times New Roman\", serif;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root[data-style=\"strict\"] {\n    --bg: #141a21;\n    --panel: #10161c;\n    --surface: #1c242e;\n    --surface-sunken: #182028;\n\n    --text: #e8edf3;\n    --text-soft: #aab6c3;\n    --text-muted: #7d8a98;\n\n    --border: rgb(232 237 243 / 12%);\n    --border-strong: rgb(232 237 243 / 22%);\n    --hover: rgb(170 182 195 / 10%);\n\n    --accent: #7fb0e0;\n    --accent-hover: #9cc3ea;\n    --accent-contrast: #0f151b;\n    --accent-soft: rgb(127 176 224 / 16%);\n    --accent-border: rgb(127 176 224 / 35%);\n\n    --radius: 4px;\n    --radius-sm: 3px;\n    --font: 13px/1.45 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n\n    --bar-bg: #0f151b;\n    --bar-text: #e8edf3;\n    --bar-text-soft: #aab6c3;\n    --bar-hover: rgb(232 237 243 / 10%);\n    --bar-border: rgb(232 237 243 / 20%);\n  }\n\n  :root[data-style=\"showcase\"] {\n    --bg: #1f1712;\n    --panel: #1f1712;\n    --surface: #2a2019;\n    --surface-sunken: #251b15;\n\n    --text: #fbeee0;\n    --text-soft: #d2b8a3;\n    --text-muted: #a08a78;\n\n    --border: rgb(251 238 224 / 12%);\n    --border-strong: rgb(251 238 224 / 22%);\n    --hover: rgb(255 154 107 / 10%);\n\n    --accent: #ff9a6b;\n    --accent-hover: #ffb28e;\n    --accent-contrast: #1f1712;\n    --accent-soft: rgb(255 154 107 / 16%);\n    --accent-border: rgb(255 154 107 / 35%);\n\n    --radius: 16px;\n    --radius-sm: 12px;\n    --font: 15px/1.6 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n    --font-display: Georgia, \"Times New Roman\", serif;\n  }\n}\n\n/* Засечки только у заголовков «Витрины»: токен задан лишь её блоками, и\n   правило ограничено стилем, чтобы остальные заголовки наследовали шрифт. */\n:root[data-style=\"showcase\"] :is(h1, h2, .app-bar__title) {\n  font-family: var(--font-display);\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbody {\n  font: var(--font);\n  margin: 0;\n  color: var(--text);\n  background: var(--bg);\n}\n\n/* [hidden] обязан побеждать любой display этого файла: правило браузера\n   авторскому проигрывает, и скрытый элемент с собственным display остаётся на\n   экране. */\n[hidden] {\n  display: none !important;\n}\n\n/* ── Каркас экрана ─────────────────────────────────────────────────────── */\n\n/* Шапка липкая: рабочий список обычно длиннее экрана, и без неё переход в\n   соседний раздел требует прокрутки в начало. */\n.app-bar {\n  position: sticky;\n  top: 0;\n  z-index: 5;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 12px 14px;\n  padding: 14px 24px;\n  background: var(--bar-bg);\n  border-bottom: 1px solid var(--border);\n  /* Внутри шапки текстовые токены переназначены на токены шапки: бренд,\n     название, навигация и зритель читаются и на тёмной шапке «Строгого»;\n     граница — тоже, иначе обводка текущего пункта навигации на ней пропадает. */\n  --text: var(--bar-text);\n  --text-soft: var(--bar-text-soft);\n  --hover: var(--bar-hover);\n  --border: var(--bar-border);\n  color: var(--text);\n}\n\n/* Бренд ведёт в раздел приложений Искры — дорога назад из открытого\n   приложения. Знак рисует inline SVG, цвета — классы ниже: атрибут style\n   политика содержимого запрещает. */\n.app-bar__brand {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  padding: 3px 8px 3px 4px;\n  margin-left: -4px;\n  border-radius: var(--radius-sm);\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--text-soft);\n  text-decoration: none;\n  white-space: nowrap;\n}\n\na.app-bar__brand:hover {\n  color: var(--text);\n  background: var(--hover);\n}\n\n.app-bar__brand b {\n  color: var(--text);\n  font-weight: 650;\n}\n\n.app-bar__logo {\n  flex: none;\n}\n\n.app-bar__logo-bg {\n  fill: var(--accent);\n}\n\n.app-bar__logo-spark {\n  fill: var(--accent-contrast);\n}\n\n.app-bar__sep {\n  color: var(--text-muted);\n}\n\n.app-bar__title {\n  margin: 0;\n  font-size: 17px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  min-width: 0;\n}\n\n.app-bar__spacer {\n  flex: 1 1 auto;\n}\n\n/* Зритель: кто смотрит приложение. Только показ — доступ решает JWT. */\n.app-bar__viewer {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  font-size: 13px;\n  color: var(--text-soft);\n}\n\n/* Длинное имя обрезается многоточием, а не распирает шапку шире окна. */\n.app-bar__viewer-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.app-bar__avatar {\n  display: inline-grid;\n  place-items: center;\n  width: 24px;\n  height: 24px;\n  border-radius: 50%;\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--text);\n  background: var(--accent-soft);\n  border: 1px solid var(--accent-border);\n  flex: none;\n}\n\n/* На узкой ширине бренд, навигация и зритель остаются первой строкой, а\n   название уходит второй во всю ширину. */\n@media (max-width: 560px) {\n  .app-bar__sep {\n    display: none;\n  }\n\n  .app-bar__title {\n    order: 1;\n    flex: 1 0 100%;\n  }\n\n  /* Остаётся аватар; имя скрыто только визуально — программа чтения экрана\n     его читает, а мышь видит подсказку title. */\n  .app-bar__viewer-name {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    overflow: hidden;\n    clip-path: inset(50%);\n    white-space: nowrap;\n  }\n}\n\n/* Полоса содержимого задаётся элементом, а не классом: экран без единого\n   класса обязан быть свёрстан. .page — то же самое явно, для разметки, где\n   main занят другим. */\nmain,\n.page {\n  max-width: var(--page-width);\n  margin: 0 auto;\n  padding: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n/* Список во всю ширину окна: восемь колонок в 1180 пикселях сжимают текстовые\n   до неузнаваемости, при том что место на мониторе есть. */\n.page--wide {\n  max-width: none;\n}\n\nmain > h1,\n.page > h1 {\n  margin: 0;\n  font-size: 21px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n}\n\nmain > h2,\n.page > h2 {\n  margin: 8px 0 0;\n  font-size: 15px;\n  font-weight: 600;\n}\n\n/* Мера строки: на широком мониторе строка в 200 символов теряется при возврате\n   к началу. Ограничение берут только абзацы без класса — классом размечают и\n   строку кнопок, и строку состояния, а им ширина нужна своя. */\nmain > p:not([class]),\n.page > p:not([class]),\n.hint {\n  max-width: 70ch;\n}\n\n/* Пояснение к экрану: тон ниже данных, иначе спорит с ними за внимание. */\n.hint {\n  color: var(--text-soft);\n  margin: 0;\n}\n\n/* ── Ссылки и навигация ────────────────────────────────────────────────── */\n\na {\n  color: var(--accent);\n  text-decoration-color: var(--accent-border);\n  text-underline-offset: 3px;\n}\n\na:hover {\n  color: var(--accent-hover);\n}\n\n.nav {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin: 0;\n}\n\n.nav a {\n  padding: 5px 11px;\n  border-radius: 999px;\n  color: var(--text-soft);\n  text-decoration: none;\n  border: 1px solid transparent;\n}\n\n.nav a:hover,\n.nav a[aria-current=\"page\"] {\n  color: var(--text);\n  background: var(--hover);\n  border-color: var(--border);\n}\n\n.nav a[aria-current=\"page\"] {\n  font-weight: 600;\n}\n\n/* ── Карточка ──────────────────────────────────────────────────────────── */\n\n.card {\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow);\n}\n\n.card--pad {\n  padding: 16px;\n}\n\n/* Карточка под таблицу «подпись — число»: во всю ширину страницы она выглядит\n   пустой, потому что данных в ней два столбца. */\n.card--narrow {\n  max-width: 560px;\n}\n\n/* ── Кнопки ────────────────────────────────────────────────────────────── */\n\n/* Три роли: обычное действие (по умолчанию), главное действие экрана\n   (.btn-primary) и разрушительное (.btn-danger). Четвёртой роли нет намеренно —\n   экран, где выделены все кнопки, не выделяет ни одной. */\nbutton {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  font: inherit;\n  font-weight: 500;\n  padding: 8px 16px;\n  border-radius: var(--radius-sm);\n  border: 1px solid var(--border-strong);\n  background: var(--surface);\n  color: var(--text);\n  cursor: pointer;\n  transition: background-color 0.12s ease, border-color 0.12s ease, opacity 0.12s ease;\n}\n\nbutton:hover:not(:disabled) {\n  background: var(--hover);\n}\n\n/* Фокус виден только с клавиатуры: кольцо после каждого клика мышью читается\n   как «элемент остался активным» и сбивает при быстрой работе. */\nbutton:focus-visible,\na:focus-visible,\ninput:focus-visible,\nselect:focus-visible,\ntextarea:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n\nbutton:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.btn-primary {\n  background: var(--accent);\n  border-color: var(--accent);\n  color: var(--accent-contrast);\n}\n\n.btn-primary:hover:not(:disabled) {\n  background: var(--accent-hover);\n  border-color: var(--accent-hover);\n}\n\n.btn-danger {\n  color: var(--danger);\n  border-color: var(--danger-border);\n  background: transparent;\n}\n\n.btn-danger:hover:not(:disabled) {\n  background: var(--danger-soft);\n}\n\n/* Действие внутри строки таблицы: меньше основной кнопки, чтобы не спорить с\n   действием всего экрана. */\n.btn-row {\n  margin-left: 10px;\n  padding: 3px 10px;\n  font-size: 12.5px;\n  border-radius: 999px;\n}\n\n.actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  margin: 0;\n}\n\n/* Вертикальная стопка с одинаковым просветом: без неё соседние блоки внутри\n   карточки слипаются, а собственные margin у каждого из них разъезжаются по\n   значениям. */\n.stack {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n/* Панель действий: кнопки и строка состояния одной строкой. Сообщение стоит\n   справа от кнопок, а не под ними: под кнопкой оно отодвигает содержимое вниз\n   ровно в тот момент, когда человек целится в следующую строку списка. На\n   узком экране строка переносится, сообщение уходит под кнопки. */\n.toolbar {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 10px 14px;\n}\n\n.toolbar .actions {\n  flex: 0 0 auto;\n}\n\n/* Остаток ширины отдаётся сообщению; 320px — порог, ниже которого оно уже не\n   читается в строку и уезжает на следующую. */\n.toolbar .status {\n  flex: 1 1 320px;\n  min-width: 0;\n}\n\n/* ── Строка состояния ──────────────────────────────────────────────────── */\n\n/* Высота держится всегда: появление сообщения дёргало бы кнопки и таблицу вниз\n   ровно в тот момент, когда человек целится в кнопку. */\n.status {\n  min-height: 34px;\n  margin: 0;\n  display: flex;\n  align-items: center;\n  color: var(--text-soft);\n}\n\n.status--ok,\n.status--warn,\n.status--error {\n  padding: 6px 12px;\n  border-radius: var(--radius-sm);\n  border-left: 3px solid transparent;\n}\n\n/* Итог действия и отказ различаются цветом: «Добавлено документов: 12» тем же\n   красным, что и «источник недоступен», читается как ошибка. */\n.status--ok {\n  color: var(--success);\n  background: var(--success-soft);\n  border-left-color: var(--success);\n}\n\n/* Частичный результат — не отказ и не успех. */\n.status--warn {\n  color: var(--accent);\n  background: var(--accent-soft);\n  border-left-color: var(--accent);\n}\n\n.status--error {\n  color: var(--danger);\n  background: var(--danger-soft);\n  border-left-color: var(--danger);\n}\n\n/* ── Таблицы ───────────────────────────────────────────────────────────── */\n\n.table-wrap {\n  overflow: auto;\n  border-radius: var(--radius);\n}\n\ntable {\n  border-collapse: separate;\n  border-spacing: 0;\n  width: 100%;\n  /* Суммы и количества выравниваются по разряду: пропорциональные цифры в\n     столбце чисел читаются как числа разной длины. */\n  font-variant-numeric: tabular-nums;\n}\n\nth {\n  position: sticky;\n  top: 0;\n  z-index: 1;\n  text-align: left;\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  background: var(--surface-sunken);\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--border);\n  white-space: nowrap;\n}\n\ntd {\n  padding: 11px 14px;\n  border-bottom: 1px solid var(--border);\n  vertical-align: top;\n}\n\ntbody tr:last-child td {\n  border-bottom: 0;\n}\n\ntbody tr:hover td {\n  background: var(--hover);\n}\n\n/* Числовая колонка: правое выравнивание и запрет переноса. «49656.24»,\n   разорванное на две строки, читается как два разных числа. */\ntd.num,\nth.num {\n  text-align: right;\n}\n\ntd.num {\n  white-space: nowrap;\n}\n\n/* Таблица «подпись — число»: во всю ширину экрана число уезжает от своей\n   подписи на полметра монитора, и строку приходится читать линейкой. */\n.pairs {\n  max-width: 520px;\n}\n\n.pairs td:last-child,\n.pairs th:last-child {\n  text-align: right;\n}\n\n/* Пустой список — это состояние, а не отсутствие ответа: таблица с одними\n   заголовками выглядит как незагрузившийся экран. */\n.empty {\n  color: var(--text-muted);\n  text-align: center;\n  padding: 28px 14px;\n}\n\n/* ── Бейджи ────────────────────────────────────────────────────────────── */\n\n/* Состояние пилюлей: в колонке из одинаковых слов глаз ищет нужную строку\n   дольше, чем по цветовому пятну. Варианты названы по значению, а не по\n   состоянию предметной области: приложение сопоставляет свои состояния\n   значениям, и палитра не растёт вместе с их числом. */\n.badge {\n  display: inline-block;\n  padding: 3px 10px;\n  border-radius: 999px;\n  font-size: 12.5px;\n  font-weight: 500;\n  white-space: nowrap;\n  color: var(--text-soft);\n  background: var(--hover);\n  border: 1px solid var(--border);\n}\n\n.badge--accent {\n  color: var(--accent);\n  background: var(--accent-soft);\n  border-color: var(--accent-border);\n}\n\n.badge--success {\n  color: var(--success);\n  background: var(--success-soft);\n  border-color: transparent;\n}\n\n.badge--danger {\n  color: var(--danger);\n  background: var(--danger-soft);\n  border-color: var(--danger-border);\n}\n\n/* Пометка рядом с бейджем — не часть состояния: своим цветом она спорила бы с\n   пилюлей, поэтому идёт тоном ниже и рядом. */\n.badge-note {\n  margin-left: 6px;\n  color: var(--text-muted);\n  font-size: 12.5px;\n}\n\n/* ── Поля формы ────────────────────────────────────────────────────────── */\n\n/* Раздел группирует поля по смыслу: пятнадцать полей подряд без деления\n   читаются как анкета, в которой каждый раз ищешь нужную строку заново. */\n.section__title {\n  margin: 0 0 8px;\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n}\n\n.fields-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 10px 12px;\n}\n\n.field {\n  display: block;\n  margin: 0;\n  min-width: 0;\n}\n\n/* Поле во всю ширину сетки: адрес или наименование в две колонки не помещается\n   и переносится там, где переносить нечего. */\n.field--wide {\n  grid-column: 1 / -1;\n}\n\n.field__label {\n  display: block;\n  margin-bottom: 4px;\n  font-size: 12.5px;\n  color: var(--text-soft);\n}\n\ninput,\nselect,\ntextarea {\n  display: block;\n  width: 100%;\n  padding: 8px 10px;\n  font: inherit;\n  color: var(--text);\n  background: var(--surface);\n  border: 1px solid var(--border-strong);\n  border-radius: var(--radius-sm);\n  font-variant-numeric: tabular-nums;\n}\n\ninput:focus,\nselect:focus,\ntextarea:focus {\n  border-color: var(--accent);\n}\n\n/* Одиночное поле не растягивается во всю ширину экрана: строка ввода в тысячу\n   пикселей читается как промах раскладки, а не как приглашение писать длинно.\n   В сетке ширину задаёт колонка, поэтому там ограничение снимается. */\ninput,\nselect,\ntextarea {\n  max-width: 32rem;\n}\n\n.field input,\n.field select,\n.field textarea {\n  max-width: none;\n}\n\nfieldset {\n  border: 0;\n  padding: 0;\n  margin: 0;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n/* Незаполненное поле видно до всякой проверки: искать его перечитыванием формы\n   — самая долгая часть работы. Подсветка снимается сама, как только в поле\n   появляется значение. */\n.is-empty {\n  background: var(--accent-soft);\n  border-color: var(--accent-border);\n}\n\n/* Отказ приёмника поверх подсветки: красный говорит «это уже отправляли и не\n   приняли», рыжий — «здесь пусто». */\n.invalid {\n  border-color: var(--danger);\n  background: var(--danger-soft);\n}\n\n/* ── Крутилка длительного действия ─────────────────────────────────────── */\n\n/* Показывается классом is-busy на самом действии: отдельная строка состояния\n   уводит взгляд с того места, куда человек только что нажал. Кнопка на это\n   время выключена, но приглушена меньше обычного disabled — иначе анимация\n   читается как подвисшая. */\n.spinner {\n  display: none;\n  width: 14px;\n  height: 14px;\n  border: 2px solid currentColor;\n  border-right-color: transparent;\n  border-radius: 50%;\n  opacity: 0.75;\n  animation: spin 0.7s linear infinite;\n}\n\n.is-busy .spinner {\n  display: inline-block;\n}\n\nbutton.is-busy:disabled {\n  opacity: 0.8;\n  cursor: progress;\n}\n\n@keyframes spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n/* Уважение к настройке «меньше движения»: вращение остаётся признаком работы,\n   но перестаёт мельтешить. */\n@media (prefers-reduced-motion: reduce) {\n  .spinner {\n    animation-duration: 2.4s;\n  }\n}\n\n/* ── Раскладки макетов ─────────────────────────────────────────────────── */\n\n/* Меню слева (navPosition: \"side\"): шапка во всю ширину, под ней меню и\n   содержимое. Разделов больше, чем помещается в строку шапки. */\n.app-shell--side {\n  display: grid;\n  grid-template-columns: 220px minmax(0, 1fr);\n  grid-template-rows: auto 1fr;\n  min-height: 100vh;\n}\n\n.app-shell--side > .app-bar {\n  grid-column: 1 / -1;\n}\n\n.app-shell--side > main {\n  width: 100%;\n}\n\n.side-nav {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding: 16px 10px;\n  background: var(--panel);\n  border-right: 1px solid var(--border);\n}\n\n.side-nav a {\n  display: block;\n  padding: 7px 12px;\n  border-radius: var(--radius-sm);\n  color: var(--text-soft);\n  text-decoration: none;\n}\n\n.side-nav a:hover {\n  color: var(--text);\n  background: var(--hover);\n}\n\n.side-nav a[aria-current=\"page\"] {\n  color: var(--text);\n  background: var(--hover);\n  font-weight: 600;\n}\n\n/* Плитки цифр дашборда: сколько влезет в строку, не уже 160px. */\n.kpis {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n  gap: 12px;\n}\n\n.kpi {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 14px 16px;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n}\n\n.kpi__label {\n  font-size: 12.5px;\n  color: var(--text-soft);\n}\n\n.kpi__value {\n  font-size: 22px;\n  font-weight: 600;\n  font-variant-numeric: tabular-nums;\n  letter-spacing: -0.01em;\n}\n\n/* «Список + карточка»: список уже карточки, на узком — одна колонка. */\n.split {\n  display: grid;\n  grid-template-columns: minmax(220px, 1fr) 2fr;\n  gap: 16px;\n  align-items: start;\n}\n\n/* Выбираемый список: выбранная строка помечается aria-current=\"true\". */\n.list-select {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin: 0;\n  padding: 6px;\n  list-style: none;\n  background: var(--surface);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n}\n\n.list-select__item {\n  display: block;\n  padding: 8px 10px;\n  border-radius: var(--radius-sm);\n  color: var(--text);\n  text-decoration: none;\n}\n\n.list-select__item:hover {\n  background: var(--hover);\n}\n\n.list-select__item[aria-current=\"true\"] {\n  background: var(--accent-soft);\n  box-shadow: inset 3px 0 0 var(--accent);\n  font-weight: 600;\n}\n\n/* Шаги мастера: пройденные, текущий и оставшиеся различаются кружком. */\n.steps {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px 20px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  counter-reset: step;\n}\n\n.step {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  color: var(--text-muted);\n  counter-increment: step;\n}\n\n.step::before {\n  content: counter(step);\n  display: inline-grid;\n  place-items: center;\n  width: 24px;\n  height: 24px;\n  border-radius: 50%;\n  font-size: 12px;\n  font-weight: 600;\n  border: 1px solid var(--border-strong);\n  background: var(--surface);\n}\n\n.step--done {\n  color: var(--text-soft);\n}\n\n.step--done::before {\n  content: \"✓\";\n  color: var(--accent);\n  border-color: var(--accent-border);\n  background: var(--accent-soft);\n}\n\n.step--current {\n  color: var(--text);\n  font-weight: 600;\n}\n\n.step--current::before {\n  color: var(--accent-contrast);\n  background: var(--accent);\n  border-color: var(--accent);\n}\n\n@media (max-width: 720px) {\n  .app-shell--side {\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-rows: auto auto 1fr;\n  }\n\n  /* Меню становится горизонтальной полосой под шапкой. */\n  .side-nav {\n    flex-direction: row;\n    overflow-x: auto;\n    padding: 8px 16px;\n    border-right: 0;\n    border-bottom: 1px solid var(--border);\n  }\n\n  .side-nav a {\n    white-space: nowrap;\n  }\n\n  .split {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n\n/* ── Узкое окно ────────────────────────────────────────────────────────── */\n\n@media (max-width: 700px) {\n  main,\n  .page {\n    padding: 16px;\n  }\n\n  .app-bar {\n    padding: 12px 16px;\n  }\n\n  .fields-grid {\n    grid-template-columns: 1fr;\n  }\n}\n";
